    let bufA = a < 0 ? a + 0x10000 : a;
    bytes.push((bufA >> 8) & 0xFF, bufA & 0xFF);

    let bufB = b < 0 ? b + 0x10000 : b;
    bytes.push((bufB >> 8) & 0xFF, bufB & 0xFF);
  } else if (command && command.op === 'lift') {
    const val = command.position === 'up' ? 1 : 0;
    bytes = [0x11, 0x06, 0x02, 0x00, 0x00, val];
  } else if (command && command.op === 'grip') {
    const val = command.state === 'closed' ? 1 : 0;
    bytes = [0x11, 0x06, 0x02, 0x01, 0x00, val];
  } else {
    throw new Error('Unknown command type');
  }

  const crc = crc16(bytes);
  bytes.push(crc & 0xFF, (crc >> 8) & 0xFF);
  return bytesToHex(bytes);
}

function decode(rawReply) {
  if (!rawReply || typeof rawReply !== 'string') {
    throw new Error('Invalid reply: not a string');
  }
  const bytes = hexToBytes(rawReply);
  if (bytes.length < 5) {
    throw new Error('Reply too short');
  }

  const unit = bytes[0];
  if (unit !== 0x11) {
    throw new Error('Unit address mismatch');
  }

  // Check CRC first
  const dataWithoutCrc = bytes.slice(0, bytes.length - 2);
  const receivedCrc = bytes[bytes.length - 2] | (bytes[bytes.length - 1] << 8);
  const calculatedCrc = crc16(dataWithoutCrc);
  if (receivedCrc !== calculatedCrc) {
    throw new Error('CRC mismatch');
  }

  const func = bytes[1];
  if ((func & 0x80) !== 0) {
    if (bytes.length !== 5) {
      throw new Error('Invalid exception frame length');
    }
    const errCode = bytes[2];
    throw new Error('Modbus exception code: ' + errCode);
  }

  if (func === 0x17) {
    if (bytes.length !== 11) {
      throw new Error('Invalid 0x17 reply length');
    }
    const byteCount = bytes[2];
    if (byteCount !== 6) {
      throw new Error('Invalid 0x17 byte count');
    }
    let rawA = (bytes[3] << 8) | bytes[4];
    if (rawA & 0x8000) rawA -= 0x10000;
    let rawB = (bytes[5] << 8) | bytes[6];
    if (rawB & 0x8000) rawB -= 0x10000;
    const flags = (bytes[7] << 8) | bytes[8];

    const applied = [rawA / 10000, rawB / 10000];
    const limited = (flags & 0x0001) !== 0;
    return { applied, limited };
  } else if (func === 0x06) {
    if (bytes.length !== 8) {
      throw new Error('Invalid 0x06 reply length');
    }
    const reg = (bytes[2] << 8) | bytes[3];
    const val = (bytes[4] << 8) | bytes[5];
    if (reg === 0x0200) {
      if (val !== 0 && val !== 1) {
        throw new Error('Invalid lift value in reply');
      }
      const position = val === 1 ? 'up' : 'down';
      return { applied: { op: 'lift', position }, limited: false };
    } else if (reg === 0x0201) {
      if (val !== 0 && val !== 1) {
        throw new Error('Invalid grip value in reply');
      }
      const state = val === 1 ? 'closed' : 'open';
      return { applied: { op: 'grip', state }, limited: false };
    } else {
      throw new Error('Unsupported register in 0x06 reply');
    }
  } else {
    throw new Error('Unsupported function code in reply: ' + func);
  }
}

